"code": "	
	tagPath = value

	results = system.tag.browse(tagPath, filter = {'recursive':True})

	alarmList = []
	repeatDic = {}	
	instances = []

	for result in results.getResults():
		path = str(result['fullPath'])
		tagType = str(result['tagType'])
		if '/Alarming/' in path and tagType == 'UdtInstance':
			alarmList.append(result)		

	for r in range(len(alarmList)):
		if alarmList[r]['name'] == 'StsHiHi':
			path = str(alarmList[r]['fullPath'])
			name = alarmList[r]['name']
			unit = system.tag.readBlocking([self.view.getChild("root").custom.tagPaths.EngUnit])
			repeatDict = {
				'name':name,
				'path':path,
				'unit' : unit[0].value,
				'instanceStyle':{},
				'instancePosition':{}
			}
			instances.append(repeatDict)

	for r in range(len(alarmList)):
		if alarmList[r]['name'] != 'StsHiHi':
			if alarmList[r]['name'] != 'StsFail':
				path = str(alarmList[r]['fullPath'])
				name = alarmList[r]['name']
				unit = system.tag.readBlocking([self.view.getChild("root").custom.tagPaths.EngUnit])
				repeatDict = {
					'name':name,
					'path':path,
					'unit' : unit[0].value,
					'instanceStyle':{},
					'instancePosition':{}
				}
				instances.append(repeatDict)

	return instances",

