"code": "	tags = system.tag.browse(value)
	tagPaths = []
	for tag in tags:
		tagPaths.append(str(tag['fullPath']))
	vals = system.tag.readBlocking(tagPaths)
	ret = []
	for index in range(len(vals)):

		label = tagPaths[index].split('/')[-1]

		ret.append({'label':label,'value':vals[index]})
	return ret",

"code": "    metaData = system.tag.browse('[OEE]Heartland/W 84th st')
    tree = []

    for area in metaData:
        if area['name'] not in ['ScheduleData']:
            areaNode = {
                "label": area['name'],
                "expanded": False,
                "data": {
                    "tagPath": area['fullPath'],
                    "Navigation": False
                },
                "items": []
            }

            # Browse lines under this area
            for line in system.tag.browse(str(area['fullPath'])):
                lineNode = {
                    "label": line['name'],
                    "expanded": False,
                    "data": {
                        "tagPath": line['fullPath'],
                    	"Navigation": True
                    },
                    "items": []
                }
                areaNode['items'].append(lineNode)   # <-- inside loop

            tree.append(areaNode)                    # <-- once per area

    return tree",

