	for tag in tagPaths:
		pos =  system.tag.readBlocking(str(tag['fullPath'])+'/Order')[0].value
		instances.append({'tagPath':str(tag['fullPath']),'order':pos})
	return sorted(instances, key=lambda d: d['order'] )",

