"code": "	parentTagPath = self.view.getChild("root").custom.LocalOptions[value['Area']]
	instances = []
	tags = system.tag.browse(parentTagPath).getResults()
	isFloat = True if 'analog' in str(parentTagPath).lower() else False
	startRange = 0
	endRange = len(tags)
	if not self.view.getChild("root").custom.onePage:

		startRange = 0 if self.view.getChild("root").custom.Page == 1 else self.view.getChild("root").custom.maxCardsPerPage
		endRange = self.view.getChild("root").custom.maxCardsPerPage if self.view.getChild("root").custom.Page == 1 else len(tags)



	for i in range(startRange, endRange):
		instance = {'index': i, 'tagpath': tags[i]['fullPath'], 'isFloat': isFloat, 'instanceStyle': {'classes': 'BoxShadow'}}
		instances.append(instance)
	return instances",

