"code": "	componentList = [[c] for c in value.getColumnAsList(value.getColumnIndex('Component'))]
	newDataset = system.dataset.toDataSet(['StockCode'], componentList)
	completedStock= self.view.custom.completedStock
	stockOptions = []
	for row in range(newDataset.getRowCount()):
		stockValue = str(newDataset.getValueAt(row, 'StockCode'))
		isComplete = False
		for i in range(completedStock.getRowCount()):
			if stockValue == completedStock.getValueAt(i, 'stock'):
				isComplete = True
				break
		if isComplete:
			stockLabel= 'Completed - %s'%(stockValue)
		else:
			stockLabel = '%s'%(stockValue)
		stockOptions.append([stockValue, stockLabel])

	completeStockOptions = []
	incompleteStockOptions = []
	for	stock in stockOptions:
		if 'Completed' in stock[1]:
			completeStockOptions.append(stock)
		else:
			incompleteStockOptions.append(stock)
	finalOptions = incompleteStockOptions + completeStockOptions
	stockDataset = system.dataset.toDataSet(['value', 'label'], finalOptions)
	if len(self.custom.selectedJobNumber) < 1:
		stockDataset = system.dataset.clearDataset(stockDataset)
	return stockDataset",

