"script": "	# get any chart created by this user or any chart made available publicly (null user or private=0)
	if not dbName:
		return system.dataset.toPyDataSet(system.dataset.toDataSet(['id', 'username', 'config_name', 'private', 'config', 't_stamp'], []))

	logger = system.util.getLogger('Ad Hoc Trends')
	dbInfo = next((d for d in self.view.custom.databases if '%s:%s' %(d.connector, d.Name) == dbName), False)
	if not dbInfo:
		logger.error('Unable to load charts of database "%s" because it was not found in database list (view.custom.databases).' %dbName)
		return

	if dbInfo['connector'] == 'sql':
		dbType = dbInfo['DBType']

		availableChartsQuery = self.view.rootContainer.getAvailableChartsQuery(dbType)

		if not availableChartsQuery:
			logger.debug('Unable to load charts of database "%s" because it is an unknown database type "%s".' %(dbName, dbType))
			return system.dataset.toPyDataSet(system.dataset.toDataSet(['id', 'username', 'config_name', 'private', 'config', 't_stamp'], []))

		return system.db.runPrepQuery(availableChartsQuery, [self.session.props.auth.user.userName], dbInfo['Name'])
	elif dbInfo['connector'] == 'mongodb':
		return system.mongodb.find(dbInfo['Name'], 'IgnitionV2_AdHocTrendsConfig', {
			'$and': [
				{'$or': [{'username': self.session.props.auth.user.userName}, {'username': None}, {'private': False}]},
				{'_id': {'$ne': 'config'}}]
		})
"

