"script": "	# implement your method here
	def getDelta(tagHistory):
		columns = []
		for c in tagHistory.getColumnNames():
			columns.append(c)
		columns.append("delta")

		rows = []
		preVal = None
		for x in range(tagHistory.getRowCount()):

			thisVal = tagHistory.getValueAt(x, 1)

			if preVal is None:
				delta = 0
				preVal = thisVal
			else:
				delta = thisVal - preVal
				preVal = thisVal

			if delta < 0:
				delta = 0

			rows.append([tagHistory.getValueAt(x, "t_stamp"), thisVal, int(delta)])

		return system.dataset.toDataSet(columns, rows)

	def getBinIndex(timestamp, bins):

		for x in range(bins.getRowCount()):
			if system.date.isBetween(timestamp, bins.getValueAt(x, "BinStart"), bins.getValueAt(x, "BinEnd")):
				return x
		return None


	def historyToBins(tagHistory, bins):
		deltas = getDelta(tagHistory)

		binsDict = {}
		for x in range(deltas.getRowCount()):
			binIndex = getBinIndex(deltas.getValueAt(x, "t_stamp"), bins)

			if binIndex not in binsDict.keys():
				binsDict[binIndex] = 0
			binsDict[binIndex] += deltas.getValueAt(x, "delta")

		headers = []
		for h in bins.getColumnNames():
			headers.append(h)

		headers.append("Category")
		headers.append("value")

		rows = []
		for x in range(bins.getRowCount()):
			index = bins.getValueAt(x, "Index")
			binStart = bins.getValueAt(x, "BinStart")
			binEnd = bins.getValueAt(x, "BinEnd")
			if x in binsDict.keys():
				value = binsDict[x]
			else:
				value = 0

			cat = system.date.format(binStart, "HH:mm")
			rows.append([index, binStart, binEnd, cat, value])

		return system.dataset.toDataSet(headers, rows)

	# -- main --------------------------------------

	return historyToBins(tagHistory, bins)

	"

