"code": "	headers = ["t_stamp", "value"]
	rows = []

	startDate = value["startDate"]
	value = value["historyData"]

	lastStatus = None
	for x in range(value.getRowCount()):
		blockedFlag = value.getValueAt(x, "Blocked")
		faultedFlag = value.getValueAt(x, "Faulted")
		runningFlag = value.getValueAt(x, "Running")
		starvedFlag = value.getValueAt(x, "Starved")

		if blockedFlag:
			status = 1
		elif faultedFlag:
			status = 2
		elif runningFlag:
			status = 3
		elif starvedFlag:
			status = 4
		else:
			status = 0

		if status != lastStatus:
			ts = value.getValueAt(x, "t_stamp")
			rows.append([ts, status])
			lastStatus = status
	if len(rows) == 0:
		rows = [[
			startDate,
			0
		]]
	return system.dataset.toDataSet(headers, rows)",

